Here is the commit message:
PCI: hv: Fix double ida_free in hv_pci_probe error path

If hv_pci_probe() fails after storing the domain number in
hbus->bridge->domain_nr, there is a call to free this domain_nr via
pci_bus_release_emul_domain_nr(), however, during cleanup, the bridge
release callback pci_release_host_bridge_dev() also frees the domain_nr
causing ida_free to be called on same ID twice and triggering following
warning:

  ida_free called for id=28971 which is not allocated.
  WARNING: lib/idr.c:594 at ida_free+0xdf/0x160, CPU#0: kworker/0:2/198
  Call Trace:
   pci_bus_release_emul_domain_nr+0x17/0x20
   pci_release_host_bridge_dev+0x4b/0x60
   device_release+0x3b/0xa0
   kobject_put+0x8e/0x220
   devm_pci_alloc_host_bridge_release+0xe/0x20
   devres_release_all+0x9a/0xd0
   device_unbind_cleanup+0x12/0xa0
   really_probe+0x1c5/0x3f0
   vmbus_add_channel_work+0x135/0x1a0

Fix this by letting pci core handle the free domain_nr and remove
the explicit free called in pci-hyperv driver.

Fixes: bcce8c74f1ce ("PCI: Enable host bridge emulation for PCI_DOMAINS_GENERIC platforms")
Signed-off-by: Sahil Chandna <sahilchandna@linux.microsoft.com>
Reviewed-by: Manivannan Sadhasivam <mani@kernel.org>
Reviewed-by: Saurabh Sengar <ssengar@linux.microsoft.com>
Signed-off-by: Wei Liu <wei.liu@kernel.org>

Here is the root cause:
The error path in hv_pci_probe() explicitly calls pci_bus_release_emul_domain_nr() to free the domain number, but the PCI core's bridge release function pci_release_host_bridge_dev() also frees the same domain number, causing a double ida_free warning. The driver should rely on the PCI core for cleanup.

Here is the patch:
  */
 static int hv_pci_probe(struct hv_device *hdev,
 			const struct hv_vmbus_device_id *dev_id)
 {
 	struct pci_host_bridge *bridge;
 	struct hv_pcibus_device *hbus;
 	int ret, dom;
 	u16 dom_req;
 	char *name;

 	bridge = devm_pci_alloc_host_bridge(&hdev->device, 0);
 	if (!bridge)
 		return -ENOMEM;

 	hbus = kzalloc_obj(*hbus);
 	if (!hbus)
 		return -ENOMEM;

 	hbus->bridge = bridge;
 	mutex_init(&hbus->state_lock);
 	hbus->state = hv_pcibus_init;
 	hbus->wslot_res_allocated = -1;

 	/*
 	 * The PCI bus "domain" is what is called "segment" in ACPI and other
 	 * specs. Pull it from the instance ID, to get something usually
 	 * unique. In rare cases of collision, we will find out another number
 	 * not in use.
 	 *
 	 * Note that, since this code only runs in a Hyper-V VM, Hyper-V
 	 * together with this guest driver can guarantee that (1) The only
 	 * domain used by Gen1 VMs for something that looks like a physical
 	 * PCI bus (which is actually emulated by the hypervisor) is domain 0.
 	 * (2) There will be no overlap between domains (after fixing possible
 	 * collisions) in the same VM.
 	 *
 	 * Because Gen1 VMs use domain 0, don't allow picking domain 0 here,
 	 * even if bytes 4 and 5 of the instance GUID are both zero. For wider
 	 * userspace compatibility, limit the domain ID to a 16-bit value.
 	 */
 	dom_req = hdev->dev_instance.b[5] << 8 | hdev->dev_instance.b[4];
 	dom = pci_bus_find_emul_domain_nr(dom_req, 1, U16_MAX);
 	if (dom < 0) {
 		dev_err(&hdev->device,
 			"Unable to use dom# 0x%x or other numbers", dom_req);
 		ret = -EINVAL;
 		goto free_bus;
 	}

 	if (dom != dom_req)
 		dev_info(&hdev->device,
 			 "PCI dom# 0x%x has collision, using 0x%x",
 			 dom_req, dom);

 	hbus->bridge->domain_nr = dom;
 #ifdef CONFIG_X86
 	hbus->sysdata.domain = dom;
 	hbus->use_calls = !!(ms_hyperv.hints & HV_X64_USE_MMIO_HYPERCALLS);
 #elif defined(CONFIG_ARM64)
 	/*
 	 * Set the PCI bus parent to be the corresponding VMbus
 	 * device. Then the VMbus device will be assigned as the
 	 * ACPI companion in pcibios_root_bridge_prepare() and
 	 * pci_dma_configure() will propagate device coherence
 	 * information to devices created on the bus.
 	 */
 	hbus->sysdata.parent = hdev->device.parent;
 	hbus->use_calls = false;
 #endif

 	hbus->hdev = hdev;
 	INIT_LIST_HEAD(&hbus->children);
 	INIT_LIST_HEAD(&hbus->dr_list);
 	spin_lock_init(&hbus->config_lock);
 	spin_lock_init(&hbus->device_list_lock);
 	hbus->wq = alloc_ordered_workqueue("hv_pci_%x", 0,
 					   hbus->bridge->domain_nr);
 	if (!hbus->wq) {
 		ret = -ENOMEM;
-		goto free_dom;
+		goto free_bus;
 	}

 	hdev->channel->next_request_id_callback = vmbus_next_request_id;
 	hdev->channel->request_addr_callback = vmbus_request_addr;
 	hdev->channel->rqstor_size = HV_PCI_RQSTOR_SIZE;

 	ret = vmbus_open(hdev->channel, pci_ring_size, pci_ring_size, NULL, 0,
 			 hv_pci_onchannelcallback, hbus);
 	if (ret)
 		goto destroy_wq;

 	hv_set_drvdata(hdev, hbus);

 	ret = hv_pci_protocol_negotiation(hdev, pci_protocol_versions,
 					  ARRAY_SIZE(pci_protocol_versions));
 	if (ret)
 		goto close;

 	ret = hv_allocate_config_window(hbus);
 	if (ret)
 		goto close;

 	hbus->cfg_addr = ioremap(hbus->mem_config->start,
 				 PCI_CONFIG_MMIO_LENGTH);
 	if (!hbus->cfg_addr) {
 		dev_err(&hdev->device,
 			"Unable to map a virtual address for config space\n");
 		ret = -ENOMEM;
 		goto free_config;
 	}

 	name = kasprintf(GFP_KERNEL, "%pUL", &hdev->dev_instance);
 	if (!name) {
 		ret = -ENOMEM;
 		goto unmap;
 	}

 	hbus->fwnode = irq_domain_alloc_named_fwnode(name);
 	kfree(name);
 	if (!hbus->fwnode) {
 		ret = -ENOMEM;
 		goto unmap;
 	}

 	ret = hv_pcie_init_irq_domain(hbus);
 	if (ret)
 		goto free_fwnode;

 	ret = hv_pci_query_relations(hdev);
 	if (ret)
 		goto free_irq_domain;

 	mutex_lock(&hbus->state_lock);

 	ret = hv_pci_enter_d0(hdev);
 	if (ret)
 		goto release_state_lock;

 	ret = hv_pci_allocate_bridge_windows(hbus);
 	if (ret)
 		goto exit_d0;

 	ret = hv_send_resources_allocated(hdev);
 	if (ret)
 		goto free_windows;

 	prepopulate_bars(hbus);

 	hbus->state = hv_pcibus_probed;

 	ret = create_root_hv_pci_bus(hbus);
 	if (ret)
 		goto free_windows;

 	mutex_unlock(&hbus->state_lock);
 	return 0;

 free_windows:
 	hv_pci_free_bridge_windows(hbus);
 exit_d0:
 	(void) hv_pci_bus_exit(hdev, true);
 release_state_lock:
 	mutex_unlock(&hbus->state_lock);
 free_irq_domain:
 	irq_domain_remove(hbus->irq_domain);
 free_fwnode:
 	irq_domain_free_fwnode(hbus->fwnode);
 unmap:
 	iounmap(hbus->cfg_addr);
 free_config:
 	hv_free_config_window(hbus);
 close:
 	vmbus_close(hdev->channel);
 destroy_wq:
 	destroy_workqueue(hbus->wq);
-free_dom:
-	pci_bus_release_emul_domain_nr(hbus->bridge->domain_nr);
 free_bus:
 	kfree(hbus);
 	return ret;
 }



